import itertools

# 1. Generate all sums m = x^2 + y^2 for 1 <= x < y <= 20
sums = set()
pairs_map = {}
for x, y in itertools.combinations(range(1, 21), 2):
    m = x**2 + y**2
    sums.add(m)
    if m not in pairs_map:
        pairs_map[m] = []
    pairs_map[m].append((x, y))

# 2. Sort the unique sums
sorted_sums = sorted(list(sums))

# 3. Identify the 20th smallest value (remembering 0-indexing)
if len(sorted_sums) >= 20:
    m_20 = sorted_sums[19]

    # 4. List the corresponding pairs for the first 20 smallest sums
    first_20_sums = sorted_sums[:20]
    results = {}
    for m in first_20_sums:
        results[m] = pairs_map[m]

    print(f"The 20th smallest unique sum (m_20) is: {m_20}")
    print("\n--- First 20 Smallest Unique Sums and their Pairs ---")
    for m, pairs in sorted(results.items()):
        print(f"m = {m}: Pairs = {pairs}")
else:
    print("Fewer than 20 unique sums found.")

# Generate sums of two squares m = x^2 + y^2 for 1 <= x < y <= 15
sums = set()
for x in range(1, 16):
    for y in range(x + 1, 16):
        m = x**2 + y**2
        sums.add(m)

# Sort the unique sums
sorted_sums = sorted(list(sums))

print(f"Total number of unique sums found: {len(sorted_sums)}")

# Check the 20th smallest unique value (index 19)
if len(sorted_sums) >= 20:
    twenty_sixth_smallest = sorted_sums[19]
    print(f"The 20th smallest unique sum is: {twenty_sixth_smallest}")
else:
    print("Fewer than 20 unique sums were found.")

# If 68 is the 20th smallest, find the pairs (x, y) that generate it
if twenty_sixth_smallest == 68:
    pairs_for_68 = []
    for x in range(1, 16):
        for y in range(x + 1, 16):
            if x**2 + y**2 == 68:
                pairs_for_68.append((x, y))
    print(f"Pairs (x, y) generating 68: {pairs_for_68}")
else:
    print("The 20th smallest unique sum is not 68.")
